"/* ==========================================================================
   Apex University Portal - Modern & Colorful Design System
   ========================================================================== */

:root {
  /* Vibrant Primary Palette */
  --primary-600: #6366f1;
  --primary-700: #4f46e5;
  --primary-800: #4338ca;
  --primary-50: #eef2ff;
  --primary-100: #e0e7ff;
  --primary-gradient: linear-gradient(135deg, #6366f1 0%, #a855f7 100%);
  --secondary-gradient: linear-gradient(135deg, #3b82f6 0%, #06b6d4 100%);
  --sunset-gradient: linear-gradient(135deg, #f43f5e 0%, #fb923c 100%);
  --emerald-gradient: linear-gradient(135deg, #10b981 0%, #059669 100%);
  --dark-gradient: linear-gradient(135deg, #1e1b4b 0%, #312e81 100%);
  --hero-bg: linear-gradient(135deg, #1e1e38 0%, #2e1065 50%, #1e1b4b 100%);

  /* Accent Colors */
  --accent-pink: #ec4899;
  --accent-cyan: #06b6d4;
  --accent-amber: #f59e0b;
  --accent-green: #10b981;
  --accent-purple: #8b5cf6;
  --accent-rose: #f43f5e;
  --accent-blue: #3b82f6;

  /* Department Colors */
  --dept-cse: #6366f1;
  --dept-cse-bg: #e0e7ff;
  --dept-math: #0ea5e9;
  --dept-math-bg: #e0f2fe;
  --dept-ece: #f59e0b;
  --dept-ece-bg: #fef3c7;
  --dept-cogs: #ec4899;
  --dept-cogs-bg: #fce7f3;
  --dept-econ: #10b981;
  --dept-econ-bg: #d1fae5;
  --dept-biol: #8b5cf6;
  --dept-biol-bg: #ede9fe;

  /* Neutrals & Surfaces */
  --bg-page: #f8fafc;
  --bg-card: #ffffff;
  --bg-card-subtle: #f1f5f9;
  --border-light: #e2e8f0;
  --border-focus: #818cf8;

  /* Typography Colors */
  --text-main: #0f172a;
  --text-muted: #64748b;
  --text-light: #94a3b8;
  --text-inverse: #ffffff;

  /* Shadows */
  --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.08), 0 2px 4px -2px rgba(0, 0, 0, 0.06);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -4px rgba(0, 0, 0, 0.08);
  --shadow-xl: 0 20px 25px -5px rgba(0, 0, 0, 0.12), 0 8px 10px -6px rgba(0, 0, 0, 0.08);
  --sha
